    while i < n:
        c = s[i]
        if c.isspace(): i+=1; continue
        if c == '-' and s[i:i+2]=='--':
            j=s.find('\\n',i); i = n if j<0 else j; continue
        if c == '/' and s[i:i+2]=='/*':
            j=s.find('*/',i); i = n if j<0 else j+2; continue
        m = re.match(r\"[A-Za-z_\\u00b5-\\u00fa][A-Za-z0-9_\\u00b5-\\u00fa'\\u0300-\\u036f\\.]*\", s[i:])
        if m: out.append(m.group()); i+=len(m.group()); continue
        m = re.match(r\"\\d+\", s[i:])
        if m: out.append(m.group()); i+=len(m.group()); continue
        out.append(c); i+=1
    return out
def sym_join(toks):
    # merge consecutive symbols (e.g. ⟨_,) into one token
    out=[]; 
