def List.Disjoint.{u_1} : {α : Type u_1} → List α → List α → Prop :=
fun {α} l₁ l₂ => ∀ ⦃a : α⦄, a ∈ l₁ → a ∈ l₂ → False
def Imperative.isDefined : {P : PureExpr} → SemanticStore P → List P.Ident → Prop :=
fun {P} σ vs => ∀ (v : P.Ident), v ∈ vs → (σ v).isSome = true
def Imperative.isNotDefined : {P : PureExpr} → SemanticStore P → List P.Ident → Prop :=
fun {P} σ vs => ∀ (v : P.Ident), v ∈ vs → σ v = none
